create table if not exists public.onboarding_steps (
  key text primary key, phase text not null, sort int not null, title text not null,
  customer_text text not null, needs text, who text, duration text,
  readiness text not null default 'ukjent' check (readiness in ('klar','manuelt','ukjent','mangler')),
  internal_note text, guide_slug text references public.integration_guides(slug) on delete set null,
  updated_at timestamptz default now()
);
create table if not exists public.onboarding_progress (
  id uuid primary key default gen_random_uuid(), customer_name text not null, step_key text not null references public.onboarding_steps(key) on delete cascade,
  done_at timestamptz not null default now(), done_by text, note text, unique (customer_name, step_key)
);
alter table public.onboarding_steps enable row level security;
alter table public.onboarding_progress enable row level security;
drop policy if exists "ob steps read" on public.onboarding_steps;
drop policy if exists "ob steps update" on public.onboarding_steps;
create policy "ob steps read" on public.onboarding_steps for select to authenticated using (true);
create policy "ob steps update" on public.onboarding_steps for update to authenticated using (true) with check (true);
drop policy if exists "ob prog read" on public.onboarding_progress;
drop policy if exists "ob prog insert" on public.onboarding_progress;
drop policy if exists "ob prog delete" on public.onboarding_progress;
create policy "ob prog read" on public.onboarding_progress for select to authenticated using (true);
create policy "ob prog insert" on public.onboarding_progress for insert to authenticated with check (true);
create policy "ob prog delete" on public.onboarding_progress for delete to authenticated using (true);
revoke all on public.onboarding_steps from anon; revoke all on public.onboarding_progress from anon;
grant select, update on public.onboarding_steps to authenticated;
grant select, insert, delete on public.onboarding_progress to authenticated;
insert into public.onboarding_steps (key,phase,sort,title,customer_text,needs,who,duration,readiness,internal_note,guide_slug) values
('avtaler','Fase 1 · Avtaler',1,'Signer kundeavtale og databehandleravtale','Før vi henter data fra systemene dine, signerer du to avtaler: kundeavtalen (eller pilotavtalen) og en databehandleravtale. Databehandleravtalen er lovpålagt, fordi Insiqt behandler opplysninger om sjåførene dine på dine vegne – posisjon, kjøre- og hviletid og timer. Du er behandlingsansvarlig, Insiqt er databehandler.','En som har signaturrett i selskapet (daglig leder eller styreleder).','Kunden og Insiqt','15 minutter','manuelt','Avtalene finnes som utkast i Team Docs og er ikke juridisk gjennomgått. Databehandleravtalen må utvides med Scania-data, nøkkelhåndtering og underleverandører før den sendes.',null),
('informer','Fase 1 · Avtaler',2,'Informer sjåførene og drøft med tillitsvalgte','Posisjon og kjøreatferd regnes som kontrolltiltak etter arbeidsmiljøloven kapittel 9. Før du tar Insiqt i bruk, skal du drøfte det med tillitsvalgte, fortelle de ansatte hva som samles inn og hvorfor, og føre det inn i protokollen over behandlingsaktiviteter. Du får ferdige maler fra oss: informasjonsskriv til sjåførene, veiledning til kapittel 9 og protokollmal. Dette kan du gjøre parallelt med resten.','Tillitsvalgt (hvis dere har) og en liste over sjåførene.','Kunden','1–2 uker (drøftingen)','manuelt','Malene ligger som utkast i Team Docs. De bør sendes med kundeavtalen som vedlegg.',null),
('logg-inn','Fase 2 · Tilgang',3,'Logg inn i Insiqt','Du får en invitasjon på e-post fra Insiqt. Klikk lenken, velg passord og skru på totrinnsinnlogging. Insiqt viser økonomien i selskapet ditt, så kontoen bør være godt sikret.','E-postadressen du vil bruke.','Kunden','5 minutter','ukjent','Invitasjon og totrinnsinnlogging finnes i plattformen, men er ikke testet ende til ende med en ny kunde.',null),
('brukere','Fase 2 · Tilgang',4,'Inviter de som skal bruke Insiqt','Inviter dem som skal se tallene – typisk daglig leder, regnskapsansvarlig og trafikkleder – under Innstillinger → Brukere & tilgang. Gi hver person bare den tilgangen de trenger. Sjåførene bruker sjåførappen, ikke webplattformen.','Navn og e-post på dem som skal ha tilgang.','Kunden','10 minutter','ukjent','Tilgangsstyringen ser ikke ut til å virke i dag: en bruker uten tilgang til webappen ser likevel hele regnskapet. Må rettes før en kunde inviterer flere brukere.',null),
('duett','Fase 3 · Regnskap og lønn',5,'Koble til Duett','Duett er grunnlaget: inntekter og kostnader per konto. Du får en egen veiledning fra oss for å gi Insiqt lesetilgang til Duett-regnskapet. Etterpå går vi gjennom kontoene sammen, så vi vet hvilke som er drivstoff, lønn, bompenger, leie og så videre.','En person med administratortilgang i Duett. Ca. 30 minutter til gjennomgang av kontoene.','Kunden og Insiqt','1 time','manuelt','Hvordan kunden gir tilgang er ikke dokumentert – i dag kan bare Raman koble opp en ny kunde. Raman må skrive stegene før dette kan sendes til kunden.','duett'),
('lonnsart','Fase 3 · Regnskap og lønn',6,'Fortell oss hvilken lønnsart som er timer','For at timene skal stemme med lønna, må vi vite hvilken lønnsart i Duett som er den timebærende – den som angir antall arbeidstimer. Regnskapsfører eller lønnsansvarlig vet dette. Send oss navnet eller nummeret på lønnsarten.','Regnskapsfører eller lønnsansvarlig.','Kunden','5 minutter','mangler','Plattformen henter ikke denne lønnsarten ennå. Det er hovedprioriteten i gjennomgangen av integrasjoner.','duett'),
('scania','Fase 4 · Kjøretøy',7,'Koble til Scania','Insiqt henter kilometer, forbruk, posisjon og kjøretid direkte fra Scania-bilene dine – med din egen nøkkel, ikke vår. Du trenger et Data Access-abonnement (pakken Performance) hos Scania-forhandleren din og «Developer»-rollen på My Scania-kontoen. Har du det, tar det to minutter: logg inn på developer.scania.com som «FMS developer», gå til My Clients, opprett en client som heter Insiqt, og lim Client ID og Secret key inn i den sikre engangslenken vi sender deg. Secret key vises bare én gang. Mangler du abonnement eller rolle, sender vi deg et ferdig ark du kan videresende til forhandleren. Biler av andre merker kommer ikke med automatisk ennå.','My Scania-konto, Data Access Performance på bilene, og Developer-rollen.','Kunden (og Scania-forhandleren)','2 minutter til 4 uker','manuelt','Tilkoblingssiden og engangslenken finnes ikke i plattformen ennå. Bruk kundeløypen i Scania-guiden for å finne riktig løype for kunden.','scania'),
('idha','Fase 5 · Timer',8,'Koble til IDHA','Timene sjåførene registrerer i IDHA, og kjøre- og hviletiden, hentes inn slik at de kan avstemmes mot lønna. Du får en veiledning fra oss for å gi tilgang.','Administratortilgang i IDHA.','Kunden','15 minutter','mangler','IDHA vises ikke i plattformen, og hvordan kunden gir tilgang er ikke dokumentert. Raman må bekrefte om integrasjonen er live.','idha'),
('bom','Fase 6 · Kostnader per bil',9,'Bompenger','Fortell oss hvilken bompengeleverandør du har avtale med – AutoSync, SkyttelPASS eller Flyt. Med AutoSync trenger du en bedriftsavtale som gir API-tilgang. Du får da en API-nøkkel og et bedrifts-ID fra AutoSync som legges inn i Insiqt.','Navnet på bompengeleverandøren og kundenummeret ditt der.','Kunden','10 minutter (pluss avtale med AutoSync)','mangler','AutoSync-siden finnes i plattformen, men er ikke testet med ekte nøkkel. SkyttelPASS og Flyt finnes ikke.','bom'),
('drivstoff','Fase 6 · Kostnader per bil',10,'Drivstoffkort','Last ned månedens transaksjonsfil fra kortleverandøren (Circle K, Uno-X/YX eller Shell) og last den opp i Insiqt. Da fordeles drivstoffkostnaden på riktig bil.','Tilgang til kundeportalen hos drivstoffkortleverandøren.','Kunden','5 minutter per måned','mangler','Filimporten er ikke bygget ennå.','drivstoff-fil'),
('app','Fase 7 · Sjåførene',11,'Sjåførene tar i bruk appen','Sjåførene laster ned Insiqt-appen og logger inn med invitasjonen de får. I appen registrerer de dagen sin, utgifter og kjøretøysjekk.','Mobilnummer eller e-post til hver sjåfør.','Sjåførene','10 minutter per sjåfør','ukjent','Versjons- og build-nummer mangler og blokkerer tolv åpne feil. Om appen ligger i App Store og Google Play er ikke registrert i kontrollsenteret.','egen-app-timer'),
('kontroll','Fase 8 · Første gjennomgang',12,'Sjekk bilene og koblingene','Når dataene er inne, sjekker du at alle bilene står med riktig regnummer, og godkjenner hvilke kostnader og inntekter som hører til hvilken bil under Økonomioversikt → Koblinger og kontroll. Biler uten Data Access vises med regnummer – det er normalt, og noe du kan ordne med forhandleren.','Den som kjenner flåten best.','Kunden','30 minutter','ukjent','Lønn må i dag kobles til én bil per måned – fordeling på flere biler mangler (meldt i Bug Tracker).',null),
('gjennomgang','Fase 8 · Første gjennomgang',13,'Første lønnsomhetsgjennomgang med Insiqt','Vi går gjennom lønnsomhet per bil og per tur sammen med deg. Målet er at du kjenner deg igjen i tallene. Stemmer noe ikke, finner vi ut hvorfor før du tar beslutninger på dem.','Daglig leder, gjerne sammen med regnskapsansvarlig.','Kunden og Insiqt','1 time','manuelt','Rapporten «Hvilke kjøretøy taper penger» og inntektspotensialet viser tall som ikke henger sammen i dag (meldt i Bug Tracker). Sjekk dem før møtet.',null)
on conflict (key) do nothing;
